// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/api/v1", wrapper.GetCapabilities)
	router.POST(options.BaseURL+"/api/v1/credentials", wrapper.CreateCredential)
	router.DELETE(options.BaseURL+"/api/v1/credentials/:id", wrapper.DeleteCredential)
	router.GET(options.BaseURL+"/api/v1/credentials/:id", wrapper.GetCredential)
	router.GET(options.BaseURL+"/api/v1/jobs", wrapper.ListJobs)
	router.POST(options.BaseURL+"/api/v1/jobs", wrapper.CreateJob)
	router.GET(options.BaseURL+"/api/v1/jobs/:id", wrapper.GetJob)
	router.POST(options.BaseURL+"/api/v1/jobs/:id/cancel", wrapper.CancelJob)
	router.GET(options.BaseURL+"/api/v1/jobs/:id/tasks", wrapper.ListJobTasks)
	router.GET(options.BaseURL+"/api/v1/jobs/:id/tasks/:taskId", wrapper.GetJobTask)
	router.POST(options.BaseURL+"/api/v1/jobs/:id/tasks/:taskId/retry", wrapper.RetryJobTask)
	router.GET(options.BaseURL+"/api/v1/machines", wrapper.ListMachines)
	router.POST(options.BaseURL+"/api/v1/machines", wrapper.CreateMachine)
	router.DELETE(options.BaseURL+"/api/v1/machines/:id", wrapper.DeleteMachine)
	router.GET(options.BaseURL+"/api/v1/machines/:id", wrapper.GetMachine)
	router.PATCH(options.BaseURL+"/api/v1/machines/:id", wrapper.UpdateMachine)
	router.POST(options.BaseURL+"/api/v1/machines/:id/actions", wrapper.PerformMachineAction)
	router.GET(options.BaseURL+"/api/v1/machines/:id/console", wrapper.GetMachineConsole)
	router.GET(options.BaseURL+"/api/v1/machines/:id/layout", wrapper.GetMachineLayout)
	router.GET(options.BaseURL+"/healthz", wrapper.Healthz)
	router.GET(options.BaseURL+"/readyz", wrapper.Readyz)
}

